1	@model ConsolidateResultReportModel
2	@using Kendo.Mvc.UI;
3	@using EduWareDataAccess.Models;
4	@using EduWareDataAccess.ResourceFiles;
5	
6	@{
7	    ViewBag.Title = "Student Consolidate Result Report";
8	    Layout = "~/Views/Shared/_Layout_Box.cshtml";
9	
10	    ViewData["LayoutBox"] = new List<LayoutBoxModel>()
11	{
12	        new LayoutBoxModel()
13	        {
14	            BreadCrumbIndexUrl = "/ReportSubCategory/ExamResultsReports",
15	            BreadCrumbIndexText = Language.Dashboard_Reports_ExamResults,
16	            BreadCrumbActionText = Language.Dashboard_Reports_StudentConsolidateResult,
17	        },
18	    };
19	}
20	<style>
21	    .k-grid-content-expander {
22	        overflow-x: scroll;
23	    }
24	
25	    th.k-header {
26	        color: #333 !important;
27	        font-size: 15px;
28	        text-transform: uppercase;
29	        font-family: AvenirNextLTPro-Demi;
30	    }
31	
32	        th.k-header k-with-icon {
33	            vertical-align: middle !important;
34	        }
35	
36	    th.k-header {
37	        text-align: center !important;
38	    }
39	
40	</style>
41	
42	@using (Html.BeginForm("Index", "ConsolidateResultReport", FormMethod.Post, new { @id = "frmConsolidateResultReport", @class = "form-elements" }))
43	{
44	    @Html.Hidden("ReportName", "ConsolidateResultReport")
45	<div class="col-md-12 p-t-20 p-l-15 p-r-15 p-b-15">
46	    <div class="col-md-3 p-l-0">
47	        <div class="form-group cus-select">
48	            <div class="fg-line">
49	                <div class="select">
50	                    <label class="fg-label">@Html.LabelFor(x => x.SchoolStandardID)<sup>*</sup></label>
51	                    @Html.DropDownListFor(x => x.SchoolStandardID, Model.SchoolStandardIDSelectList, "Select Class", new { @id = "SchoolStandardID", @name = "SchoolStandardID", @class = "selectpicker form-control", @onchange = "FillDivision();" })
52	                </div>
53	                <span class="Error-Pull ErrorSetting">
54	                    <small>@Html.ValidationMessageFor(m => m.SchoolStandardID, null, new { Class = "ErrorSetting" })</small>
55	                </span>
56	            </div>
57	        </div>
58	    </div>
59	
60	    <div class="col-md-3 p-l-0">
61	        <div class="form-group cus-select">
62	            <div class="fg-line">
63	                <div class="select">
64	                    <label class="fg-label">@Html.LabelFor(x => x.StandardDivisionID)<sup>*</sup></label>
65	                    @Html.DropDownListFor(x => x.StandardDivisionID, Model.StandardDivisionIDSelectList, "Select Division", new { @id = "StandardDivisionID", @name = "StandardDivisionID", @class = "selectpicker form-control" })
66	                </div>
67	                <span class="Error-Pull ErrorSetting">
68	                    <small>@Html.ValidationMessageFor(m => m.StandardDivisionID, null, new { Class = "ErrorSetting" })</small>
69	                </span>
70	            </div>
71	        </div>
72	    </div>
73	
74	    <div class="col-md-3 p-l-0">
75	        <div class="form-group cus-select">
76	            <div class="fg-line">
77	                <div class="select">
78	                    <label class="fg-label">@Html.LabelFor(x => x.TermID)<sup>*</sup></label>
79	                    @Html.DropDownListFor(x => x.TermID, Model.TermIDSelectList, "Select Term", new { @id = "TermID", @name = "TermID", @class = "selectpicker form-control" })
80	                </div>
81	                <span class="Error-Pull ErrorSetting">
82	                    <small>@Html.ValidationMessageFor(m => m.TermID, null, new { Class = "ErrorSetting" })</small>
83	                </span>
84	            </div>
85	        </div>
86	    </div>
87	    <div class="col-md-2 p-b-10 p-l-0 fees-check">
88	        <div class="form-group">
89	            <div class="fg-line p-t-20">
90	                <input type="radio" name="OnlyAlumniStudents" value="0" checked="checked">All
91	                <input type="radio" name="OnlyAlumniStudents" value="1">Regular
92	                <input type="radio" name="OnlyAlumniStudents" value="2">Only Alumni
93	            </div>
94	        </div>
95	    </div>
96	    <div class="col-md-1 m-t-15 p-l-0">
97	        <button id="btnSearch" class="search" type="button"><i class="demo-icon icon-search"></i></button>
98	
99	    </div>
100	
101	</div>
102	
103	    <div class="col-md-12 cus-pager-grid p-0 m-t-0">
104	        <div id="KConsolidateResultReport" style="height: 950px;"></div>
105	    </div>
106	    <script>
107	        (function () {
108	            window.ConsolidateResultReportViewModel = {
109	                init: function () {
110	                    return this;
111	                }
112	            };
113	        })();
114	    </script>
115	    <script type="text/javascript">
116	        kendo.bind($("#frmConsolidateResultReport"), kendo.observable(window.ConsolidateResultReportViewModel.init()))
117	
118	        var kendoexportfields = [];
119	
120	        $(document).ready(function () {
121	            $.validator.unobtrusive.parse("#frmConsolidateResultReport");
122	            var validator = $("#frmConsolidateResultReport").validate();
123	            if (validator) {
124	                validator.settings.ignore = ":hidden:not(.validate-hidden):not(.validatehidden)";
125	            }
126	
127	            KendoGridHeightWithoutButton("KConsolidateResultReport");
128	
129	            kendoexportfields = [];
130	
131	            $("#SchoolStandardID").on("change", function () {
132	                FillDivision();
133	            });
134	
135	            $(document).off("click", "#KConsolidateResultReport .k-pager-refresh").on("click", "#KConsolidateResultReport .k-pager-refresh", function (e) {
136	                e.preventDefault();
137	                e.stopPropagation();
138	                $("#btnSearch").trigger("click");
139	            });
140	
141	            $("#btnSearch").click(function () {
142	                if (!$("#frmConsolidateResultReport").valid()) {
143	                    return false;
144	                }
145	
146	                var varSchoolStandardID = $("#SchoolStandardID").val();
147	                var varStandardDivisionID = $("#StandardDivisionID").val();
148	                var varTermID = $("#TermID").val();
149	                var varOnlyAlumni = $("input[name='OnlyAlumniStudents']:checked").val();
150	
151	
152	                showLoader();
153	                var group = "";
154	
155	                dataExists().done(function (response) {
156	                    if (response === false) {
157	                        hideLoader();
158	                        return;
159	                    }
160	                    $.ajax({
161	                        url: "/ConsolidateResultReport/GetStudentList",
162	                        type: "GET",
163	                        data: {
164	                            SchoolStandardID: varSchoolStandardID,
165	                            StandardDivisionID: varStandardDivisionID,
166	                            TermID: varTermID,
167	                            OnlyAlumni: varOnlyAlumni
168	                        },
169	                        dataType: "json",
170	                        success: function (response) {
171	                            group = response.groupedFields || [];
172	                            hideLoader();
173	
174	                            kendoexportfields = [];
175	                            if ($("#SchoolStandardID option:selected").val()) {
176	                                kendoexportfields.push("Class : " + $("#SchoolStandardID option:selected").text());
177	                            }
178	                            if ($("#StandardDivisionID option:selected").val()) {
179	                                kendoexportfields.push(" | Division : " + $("#StandardDivisionID option:selected").text());
180	                            }
181	                            if ($("#TermID option:selected").val()) {
182	                                kendoexportfields.push(" | Term : " + $("#TermID option:selected").text());
183	                            }
184	
185	                            const $grid = $("#KConsolidateResultReport").empty();
186	
187	                            if (response.data && response.data.length > 0) {
188	                                var aggregates = (response.aggregateFields || []).map(function (field) {
189	                                    return { field: field, aggregate: "sum" };
190	                                });
191	
192	                                $grid.kendoGrid({
193	                                    height: 900,
194	                                    dataSource: {
195	                                        data: response.data,
196	                                        //aggregate: aggregates,
197	                                        group: group,
198	                                        pageSize: 100
199	                                    },
200	                                    columns: response.columns,
201	                                    pageable: {
202	                                        pageSizes: [10, 20, 50, 100, 500],
203	                                        buttonCount: 5,
204	                                        refresh: true,
205	                                        pageSize: 100
206	                                    },
207	                                    resizable: true,
208	                                    //groupable: true,
209	                                    selectable: "single",
210	                                    filterable: {
211	                                        extra: false,
212	                                        operators: {
213	                                            string: {
214	                                                clear: "Clear",
215	                                                eq: "Is equal to",
216	                                                contains: "Contains"
217	                                            }
218	                                        }
219	                                    },
220	                                    toolbar: ["excel"],
221	                                    excel: {
222	                                        fileName: "ConsolidateResultReport.xlsx",
223	                                        filterable: true,
224	                                        allPages: true,
225	                                        proxyURL: "/Grid/Excel_Export_Save"
226	                                    },
227	                                    excelExport: ExcelExport,
228	                                    sortable: true,
229	                                    navigatable: true,
230	                                    dataBound: function () {
231	                                        var gridHeight = $("#KConsolidateResultReport .k-grid-content").outerHeight();
232	                                        if (gridHeight < 400) {
233	                                            $("#KConsolidateResultReport .k-grid-content").css("height", "400px");
234	                                        }
235	                                    }
236	                                });
237	
238	                                KendoGridHeightWithoutButton("KConsolidateResultReport");
239	                            }
240	                            else {
241	                                toastr.error("No data Found");
242	                            }
243	
244	                            hideLoader();
245	                        },
246	                        error: function (xhr, status, error) {
247	                            console.error("Error fetching data: " + error);
248	                            hideLoader();
249	                        }
250	                    });
251	                });
252	            });
253	        });
254	
255	        function FillDivision() {
256	            if ($("#SchoolStandardID").val() === "") {
257	                $("#StandardDivisionID").fillSelect([]);
258	                return;
259	            }
260	
261	            $("#StandardDivisionID").fillSelect([], {
262	                ajaxConfig: {
263	                    type: "POST",
264	                    url: '/Common/FillStandardDivisionBySchoolStandardID',
265	                    data: { p_SchoolStandardID: $("#SchoolStandardID").val() },
266	                    async: false,
267	                }
268	            });
269	        }
270	
271	        function dataExists() {
272	            let promise = $.Deferred();
273	
274	            var SchoolStandardID = $("#SchoolStandardID").val();
275	            var StandardDivisionID = $("#StandardDivisionID").val();
276	            var TermID = $("#TermID").val();
277	
278	            $.ajax({
279	                type: "Get",
280	                url: '/ConsolidateResultReport/CheckConsolidateDataExists/',
281	                data: { SchoolStandardID: SchoolStandardID, StandardDivisionID: StandardDivisionID, TermID: TermID },
282	                success: function (result) {
283	                    (result === false && toastr.error("No data"));
284	                    $("#divStudentData").html("");
285	                    promise.resolve(result);
286	                },
287	                error: function (jqXHR, exception) {
288	                    alert('Uncaught Error.n' + jqXHR.responseText);
289	                    promise.resolve(false);
290	                }
291	            });
292	            return promise;
293	        }
294	    </script>
295	}
